    [HarmonyPatch(typeof(ShipStatus), nameof(ShipStatus.RepairSystem))]
    public static class SabotagePatch
    {
        public static void Postfix(ShipStatus __instance, SystemTypes systemType, PlayerControl player, int amount)
        {
            // amount < 0 表示激活破坏，amount > 0 表示修复
            if (amount < 0)
                EventTriggers.OnSabotageStart(systemType);
